from pathlib import Path
import re,json,html
root=Path(__file__).resolve().parents[1]/'dist'
home=(root/'index.html').read_text(encoding='utf-8')
origin='https://www.metachlorian.xyz'
header=re.search(r'<header.*?</header>',home,re.S).group().replace('href="#','href="/#')
footer=re.search(r'<footer.*?</footer>',home,re.S).group()
favicon=re.search(r'<link rel="icon"[^>]+>',home).group()
def code(s):return '<pre><code>'+html.escape(s)+'</code></pre>'
pages=[
('self-hosted-video-library','Build a self-hosted AI video library','Keep your footage on your hardware and make individual shots searchable with Metachlorian. A practical Docker setup guide for a server or NAS.','Your footage, your infrastructure.',[
('why','Why index a library at shot level?','''<p>A folder tells you where a file lives. It rarely tells you where a specific moment is hiding. Metachlorian analyses each video as a sequence of shots and records visual meaning alongside motion, duration, speech, on-screen text and usage rights.</p><p>That lets you search for a description such as “slow coastal drone shots at golden hour” and narrow the results by the practical requirements of an edit. You can inspect why each result matched before adding it to a collection.</p>'''),
('requirements','What you need','''<p>For the Docker route, use a machine with Docker and the Docker Compose plugin, Git, and access to your footage. This can be a server, a compatible NAS or your development machine. Keep space available for the library database, downloaded models and generated media.</p><p>The default analysis models run on a CPU. A GPU is optional; it can accelerate supported models and enable richer local vision-language captions. The repository documents its CPU measurements and the limits of its evaluations.</p>'''),
('install','Start with Docker', '<p>Clone the repository, choose a long administrator password and point <code>FOOTAGE_DIR</code> at your real footage folder. Replace both example values before running:</p>'+code("git clone https://github.com/JeremySNR/Metachlorian\ncd Metachlorian\n\nMETACHLORIAN_ADMIN_PASSWORD='choose-a-long-password' \\\nFOOTAGE_DIR=/path/to/footage \\\n  docker compose -f deploy/docker-compose.yml up -d")+'''<p><strong>Allow the first startup to finish.</strong> The container downloads about 1.7 GB of analysis models before starting the server, so the browser may not connect immediately. Follow startup progress with <code>docker compose -f deploy/docker-compose.yml logs -f metachlorian</code> and wait until the server is listening.</p><p>Then open <code>http://&lt;host&gt;:8765</code>, replacing <code>&lt;host&gt;</code> with the server address, and sign in as <code>admin</code>. On the same machine, the host can be <code>localhost</code>.</p><p>The supplied Compose configuration mounts footage read-only and keeps application data and model files in named volumes. Review that configuration when adapting it to your storage environment.</p><p>If you prefer a native installation, the repository also documents Python 3.11, uv, model downloads, the frontend build and the local server command.</p>'''),
('first-search','Make your first search useful','''<ol><li><strong>Index a representative folder.</strong> Start with footage you know so you can judge the results.</li><li><strong>Describe a moment.</strong> Include a subject, setting or remembered line rather than only a filename.</li><li><strong>Refine your requirements.</strong> Duration, shot size and intended use help narrow the selection.</li><li><strong>Inspect the evidence.</strong> Signals carry a source, confidence and model version. Correct mistakes; human corrections take priority after reprocessing.</li></ol>'''),
('rights','Add rights before handing footage off','''<p>Record the licence, permitted uses, channels, territories, expiry and releases for each file. Individual shots can override the file-level record. When you give search an intended use, Metachlorian filters against those recorded permissions.</p><p>The software helps you apply your rights records consistently. Keep those records accurate and complete: it does not independently establish ownership or obtain missing permissions.</p>'''),
('next','Take the selects into your workflow','''<p>Build collections and export through OpenTimelineIO, FCPXML or CMX 3600 EDL, or send a package to <a href="https://github.com/JeremySNR/cutawan">Cutawan</a>. If you work with AI agents, connect the same library through <a href="/guides/mcp-video-search/">Metachlorian’s MCP server</a>.</p><p>See the <a href="https://github.com/JeremySNR/Metachlorian#quick-start">repository quick start</a>, <a href="https://github.com/JeremySNR/Metachlorian/blob/HEAD/deploy/docker-compose.yml">Compose configuration</a> and <a href="https://github.com/JeremySNR/Metachlorian/tree/HEAD/eval">published evaluation</a> for the implementation details.</p>''')]),
('mcp-video-search','Connect AI agents to your video library with MCP','Connect Metachlorian to an MCP client to search footage, inspect shots, check recorded rights and prepare editing handoffs with scoped agent access.','A shared understanding of every shot.',[
('why','Let your agent search the actual archive','''<p>Metachlorian exposes the same core library to people and AI agents. Its MCP server provides tools for shot search, detailed records, transcripts, collections and rights checks. A REST API is available as well.</p><p>An agent can begin with a creative brief, find candidate footage and inspect the evidence behind a match. The response includes shot boundaries and rights verdicts, giving downstream editing tools more useful context than a filename alone.</p>'''),
('connect','Connect over HTTP','''<p>First run Metachlorian and create an agent token in <strong>Settings → Agents</strong>. Add the server to an MCP client that supports HTTP connections. The exact configuration location depends on your client; the repository provides this connection shape:</p>'''+code('''{
  "mcpServers": {
    "metachlorian": {
      "type": "http",
      "url": "http://127.0.0.1:8765/mcp/",
      "headers": {
        "Authorization": "Bearer YOUR_AGENT_TOKEN"
      }
    }
  }
}''')+'''<p>Replace the example token with the one you created. For a shared server, use its address instead of <code>127.0.0.1</code>. Treat the token as a credential and keep it out of source control.</p>'''),
('local','Or connect locally over stdio','''<p>For a client on the same machine, the CLI can run an MCP connection over standard input and output:</p>'''+code('''{
  "mcpServers": {
    "metachlorian": {
      "command": "metachlorian",
      "args": ["mcp"],
      "env": {
        "METACHLORIAN_DATA": "/path/to/library"
      }
    }
  }
}''')+'''<p>Use the path to your library and ensure the client can find the installed <code>metachlorian</code> command. Without a token, local stdio access is read-only by default.</p>'''),
('tools','Give the agent a concrete brief','''<p>Try: “Find slow coastal shots, at least eight seconds each, for a paid social edit.” A useful workflow is:</p><ol><li><code>search_shots</code> retrieves candidates using the description, filters and intended use.</li><li><code>get_shot</code> returns detailed signals, word-timed transcripts and rights information.</li><li><code>check_rights</code> evaluates the recorded permissions for the use, channel, territory and date.</li><li><code>build_package</code>, when explicitly scoped for export, prepares selected media and timelines for an editor.</li></ol><p>The agent can also scope searches to folders or collections, use <code>find_similar</code> to explore related footage and call <code>library_stats</code> to distinguish missing footage from material that has not been indexed.</p>'''),
('permissions','Keep permissions deliberate','''<p>Agents receive <code>library:read</code> access by default. Exporting media requires <code>media:export</code>; collection edits and tag corrections have separate write scopes. Rights administration and administrator scopes are not available to agent tokens.</p><p>Every agent call is audited. Agents cannot package shots unless the recorded rights verdict is <code>allowed</code>. People can review the underlying rights records in the app.</p>'''),
('next','From a brief to an editing handoff','''<p>Metachlorian handles indexing, understanding and retrieval. <a href="https://github.com/JeremySNR/cutawan">Cutawan</a> handles editing. Together, the agent can discover the relevant footage and prepare a package with media, transcripts, timelines and a rights summary.</p><p>For photographs, explore the <a href="/guides/lightroom-classic-ai-photo-editing/">Photos and Lightroom Classic source preview</a>: the same MCP server supports image search, virtual-copy editing and render review.</p><p>Read the complete <a href="https://github.com/JeremySNR/Metachlorian/blob/HEAD/docs/agents.md">agent API guide</a> for exact parameters and scopes. To get the library running first, follow the <a href="/guides/self-hosted-video-library/">self-hosting guide</a>.</p>''')])]
pages.insert(0, (
 'find-b-roll',
 'How to find B-roll in your own video library',
 'Find B-roll by describing the shot, refine by duration and recorded rights, then export a shortlist. A practical Metachlorian workflow for video editors.',
 'Turn an editing brief into a shortlist of real shots.',
 [
  ('start', 'Start with footage you already know', '''<p>You remember filming a wide coastal shot. You do not remember the filename, the card it came from or where it begins inside a long take. Searching filenames will only help if someone named the file well. Shot-level search lets you ask about what is visible inside it.</p><p>Metachlorian is free, open-source AI footage search. <a href="/#get-started">Download the desktop app</a>, add a small, familiar folder and allow indexing and analysis to finish. The first launch downloads the analysis models. Starting small gives you a way to check whether the descriptions and search results reflect the material you actually shot.</p><p>This workflow uses example queries, not a promise that a matching shot exists in your archive. Search quality depends on the footage, completed analysis and models you have enabled.</p>'''),
  ('describe', 'Describe the visible moment first', '''<p>Begin with a subject, an action and a setting: <code>a person walking along a rocky coastline</code>. Then add requirements that matter to the edit: <code>wide, slow camera movement, at least eight seconds</code>. A practical starting query is <code>slow wide coastal drone shots at golden hour</code>.</p><p>For an interview about a journey, an abstract brief such as “the feeling of getting away” may be less useful than a set of concrete searches: <code>packing a suitcase</code>, <code>train leaving a station</code>, or <code>view through a car window</code>. Try those separately, compare the candidates, and decide which images support the story.</p><p>If you remember something that was said, search that phrase too. Metachlorian combines visual similarity with words in transcripts, on-screen text and labels; it is useful for both silent cutaways and dialogue.</p>'''),
  ('refine', 'Narrow the results without hiding good options', '''<ol><li><strong>Start broad.</strong> Search the subject before adding every technical constraint.</li><li><strong>Check the parsed query.</strong> Review the editable filters and preferences rather than assuming every word became the filter you intended.</li><li><strong>Set the usable duration.</strong> A two-second cutaway and an eight-second establishing shot have different needs. Leave room for your final trim.</li><li><strong>Inspect technical details.</strong> Check resolution and frame rate against the delivery. Review the shot itself for focus, shake and composition.</li><li><strong>Try a similar shot.</strong> Once you find a promising candidate, use visual similarity to look for another angle or a related moment.</li></ol><p>If a search is empty, remove a constraint and try again. Also check whether analysis is still running. “No results” does not always mean “not in the archive”.</p>'''),
  ('evidence', 'Review the result, not just its label', '''<p>Each result points to a shot within a source file. Open it, inspect the in and out points, and check the explanation for why it matched. A model label is evidence to review, not an editorial decision.</p><p>Metachlorian distinguishes measured signals, such as duration, from model output and human corrections. If a description or tag is wrong, correct it. Human corrections are stored separately and take priority after reprocessing. This makes the library more useful for the next search as well as the current edit.</p><p>Make a small collection of candidates. Keep a note about why each shot belongs in the sequence: establishing location, covering a cut, showing a detail, or changing pace. Your collection is a shortlist to edit from, not an automatically finished film.</p>'''),
  ('permissions', 'Check recorded permissions before export', '''<p>Record the source, licence, releases and relevant usage restrictions, then state the intended use when searching. For example, a paid-social edit may need different permissions from an editorial piece. Metachlorian filters against the rights recorded in the library and includes a verdict with results.</p><p>Keep those records accurate. A retrieved shot or an imported web video does not establish permission to reuse it. Downloaded web footage begins with unknown rights until someone reviews it.</p><p><strong>Before importing private or unlisted YouTube videos:</strong> turn off Settings → Community sharing if their metadata must remain private. New YouTube imports share machine metadata with a public community index by default, separately from hosted model settings. <a href="https://github.com/JeremySNR/Metachlorian#community-sharing">Read the complete sharing behaviour</a>.</p>'''),
  ('handoff', 'Take your shortlist into the edit', '''<p>Export selected shots through OpenTimelineIO, FCPXML or CMX 3600 EDL, or send a package to <a href="https://github.com/JeremySNR/cutawan">Cutawan</a>. Choose a format supported by your editing workflow, then check the imported timing and media paths before building the final sequence.</p><p>If an AI agent helps with selection, it can search the same library through MCP, inspect the evidence and prepare a handoff with the required scopes. Read the <a href="/guides/mcp-video-search/">MCP video search guide</a>. For a shared archive on a server or NAS, use the <a href="/guides/self-hosted-video-library/">self-hosted library guide</a>.</p><p>The useful loop is simple: describe a real moment, review a few candidates, correct mistakes, and save the shots that serve your story.</p>''')
 ]))
pages.append((
 'lightroom-classic-ai-photo-editing',
 'AI photo search and Lightroom Classic editing with Codex',
 'Find family, portrait and travel photos, compare real previews, and guide Lightroom Classic edits with Codex and MCP. Storage, setup and source-preview limits.',
 'Find the photographs that matter. Review every edit.',
 [
  ('preview', 'What is available in the Photos preview?', '''<p>Metachlorian now includes photo indexing, visual search, people, collections and an editing workflow for Lightroom Classic in its <strong>current source preview</strong>. These features are not included in the published v0.2.0 desktop installers. Start with the <a href="https://github.com/JeremySNR/Metachlorian/blob/main/docs/photos.md#start">source setup instructions</a>.</p><p>Codex, or another vision-capable agent connected through the Model Context Protocol (MCP), makes the photographic decisions. A small bundled Lightroom plug-in connects Metachlorian to the catalogue and Adobe’s renderer. It does not replace your agent or require a second AI subscription.</p><p>Editing currently targets <strong>Lightroom Classic 15.6</strong>. Automated tests cover the service, connector contracts and recovery behaviour; live Lightroom certification on macOS and Windows and real-photo preference evaluation remain pending. Try an expendable catalogue first. This is a Classic integration, not an integration with the cloud Lightroom application.</p>'''),
  ('library', 'Index a catalogue without copying your originals', '''<p>Run Metachlorian on the same computer and OS account as Lightroom Classic. Enable <strong>Photos</strong>, select <strong>Install connector files</strong>, then add the displayed <code>MetachlorianPhotos.lrplugin</code> directory through Lightroom’s <strong>File → Plug-in Manager</strong>. Choose <strong>Sync catalogue</strong> in Metachlorian to index metadata first, followed by analysis of available image renditions.</p><p>The connector uses Lightroom to access existing previews, including Smart Previews when available. It does not write directly to <code>.lrcat</code> files or create Smart Previews for the entire catalogue. An offline original can still have a searchable record; the evidence available depends on the previews Lightroom can supply.</p><p>You can also index a folder in place. JPEG, PNG, TIFF and WebP are supported through Pillow; the photo installation includes RAW and HEIC decoders. Selected folder images are imported into Lightroom in place when you start editing them. A NAS or Docker container can host video search, but cannot control a desktop Lightroom installation through this local connector.</p>'''),
  ('select', 'Choose the best images for your brief', '''<p>Start with what you want to remember or communicate. For family photographs, expression, gesture and relationships often matter as much as technical perfection. A laugh with closed eyes can be the right frame. For travel, balance people, places, details and wider context. For portraits, consider the eyes, pose, background, light and believable skin colour together.</p><p>Search combines visual content with filters for named people, dates, folders, catalogues, ratings, camera and lens. Burst grouping helps you compare related frames and avoid filling a shortlist with nearly identical moments. Names are human-confirmed; small faces, children and unusual poses need checking.</p><p>The agent receives actual previews, optional detail crops and qualified measurements of clipping, sharpness, face regions and framing. Aperture, shutter speed and ISO explain capture conditions. They are not rules for deciding whether a photograph is good. A Smart Preview cannot establish original-resolution eye focus or RAW highlight recoverability, and a generic aesthetic score cannot decide which photograph of your family matters most.</p><p>Try this brief: “Find 20 favourites from our July holiday featuring my son. Compare similar frames, include quiet moments as well as smiles, and keep some environmental photographs. Edit naturally in Lightroom on virtual copies. Inspect the renders and put the results in ‘July family favourites’.”</p>'''),
  ('codex', 'Connect Codex through the existing MCP server', '''<p>Create a token in <strong>Settings → Agents</strong> with <code>library:read</code>, <code>photos:edit</code> and <code>collections:write</code>. Search and inspection work with read-only access; editing requires its separate scope. Set <code>METACHLORIAN_TOKEN</code> in the environment used to launch Codex, and add the following to your Codex configuration:</p>'''+code('''[mcp_servers.metachlorian]
url = "http://127.0.0.1:8765/mcp/"
bearer_token_env_var = "METACHLORIAN_TOKEN"''')+'''<p>Use the server URL displayed in Photos if your desktop build uses a different port. Connect to the running server over HTTP so it owns the Lightroom connection and durable job queue. The same MCP server also supports <a href="/guides/mcp-video-search/">video search and editing handoffs</a>.</p><ol><li><code>search_photos</code> finds candidates; <code>get_photo_previews</code> supplies actual images for comparison.</li><li><code>get_photo_edit_context</code> reports the current Lightroom revision, available controls and recovery snapshots.</li><li><code>begin_photo_edits</code> creates owned virtual copies and fresh baselines.</li><li><code>apply_photo_edit</code> applies supported adjustments and produces a new Lightroom render. The agent inspects it before another refinement.</li><li><code>finish_photo_edits</code> saves visually reviewed copies to a named collection after checking their revisions.</li></ol><p>Interrupted jobs can be inspected and resumed. Reuse the same idempotency key when retrying an uncertain request; a conflict requires fresh context and review. See the <a href="https://github.com/JeremySNR/Metachlorian/blob/main/docs/photos.md#connect-codex">complete tool contract and recovery instructions</a>.</p>'''),
  ('editing', 'Improve the photograph with supported Lightroom controls', '''<p>Begin with the image’s intent, then make a small set of deliberate adjustments. Check composition and distracting edges; balance exposure and white balance; shape contrast and colour; inspect skin and highlight transitions; then evaluate detail at an appropriate scale. Compare each candidate with its baseline. This workflow allows up to three refinement rounds per edit session.</p><p>The connector validates controls available on each photograph, including their units and ranges. Supported families include exposure and tone, white balance, RGB and parametric curves, HSL, colour grading, crop and straightening, perspective, lens controls, sharpening, noise reduction, vignette and grain, plus simple subject, sky and background masks. RAW temperature is expressed in Kelvin; JPEG temperature uses relative adjustments.</p><p>Edits target owned virtual copies. Fresh Lightroom renders let the agent inspect Adobe’s actual output, while snapshots and revision checks support recovery and detect intervening human changes. A settings readback alone does not demonstrate a pleasing result.</p><p><strong>Manual or capability-gated operations:</strong> Point Color, complex mask geometry, guided perspective, healing and Generative Remove, reflection removal, Lens Blur, Enhance/AI Denoise, HDR and panorama merges, and HDR output. The workflow explains when a Lightroom handoff is needed rather than reporting an unsupported operation as completed.</p>'''),
  ('storage', 'How much storage does photo indexing use?', '''<p>Originals stay where they are. The default <strong>256 MiB cache</strong> covers retained JPEG previews and reserved temporary Lightroom renders together. Older previews are evicted; face crops are created on request. The photo model pack downloads approximately <strong>947 MB once</strong> and reuses models already installed for video analysis.</p><p>A recorded synthetic benchmark used about <strong>650 MiB for 100,000 photo records</strong>, including its reusable vector index and three face observations per image. That excludes model weights, preview storage and Lightroom-owned files. It measures index storage and retrieval, not photographic quality, and real catalogues will vary. Read the <a href="https://github.com/JeremySNR/Metachlorian/blob/main/docs/photos.md#evaluation-and-release-gates">benchmark methodology and results</a>.</p><p>Virtual copies, snapshots and Adobe AI data can grow Lightroom’s catalogue and associated files. Metachlorian’s cache budget does not govern Adobe’s storage. The approach avoids duplicating your originals, but it does need disk space for its own index.</p>'''),
  ('privacy', 'Local analysis and your chosen agent', '''<p>Photo analysis runs locally and does not enter the public video community index. Previews explicitly requested through MCP are sent to your chosen agent, which may run on a hosted service. Choose that agent with your family photographs and privacy preferences in mind.</p><p>Face embeddings are not exposed through the photo API. People are named and regrouped by human accounts, while agents have scoped access to search, inspection and editing. The catalogue remains authoritative for Lightroom settings.</p>'''),
  ('learn', 'Learn the tools and evaluate the results', '''<p>Adobe’s <a href="https://helpx.adobe.com/lightroom-classic/tutorials.html">Lightroom Classic tutorials</a> and <a href="https://jkost.com/blog/lightroom-training-videos">Julieanne Kost’s Lightroom training</a> cover composition, profiles, tone, colour, masks, detail and output. Use them to develop a visual goal and understand the tradeoffs behind each control.</p><p>The project’s <a href="https://github.com/JeremySNR/Metachlorian/blob/main/docs/research/lightroom-classic.md">research notes</a> explain the open-source tooling and learning resources. The <a href="https://github.com/JeremySNR/Metachlorian/blob/main/docs/photos.md">photo documentation</a> records the supported control families, storage model and outstanding platform checks.</p><p>Evaluate edits against untouched baselines using portraits, travel and family photographs you know. Personal preference and visible regressions matter more than a headline score. Automated tests are useful evidence about software behaviour; they do not prove that an edit looks better.</p>''')
 ]))
for slug,title,description,deck,sections in pages:
 url=f'{origin}/guides/{slug}/'
 seo_title='Lightroom Classic AI Editing with Codex' if slug=='lightroom-classic-ai-photo-editing' else title
 schema={'@context':'https://schema.org','@graph':[{'@type':'TechArticle','headline':title,'description':description,'url':url,'inLanguage':'en','about':{'@type':'SoftwareApplication','name':'Metachlorian'}},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Metachlorian','item':origin+'/'},{'@type':'ListItem','position':2,'name':title,'item':url}]}]}
 contents=''.join(f'<section id="{id}"><h2>{heading}</h2>{body}</section>' for id,heading,body in sections)
 image='metachlorian-logo.png' if slug=='lightroom-classic-ai-photo-editing' else 'search-interface.webp'
 image_alt='Metachlorian logo' if slug=='lightroom-classic-ai-photo-editing' else 'Metachlorian video search interface'
 cta='''<h2>Try the Photos source preview.</h2><p>Build from the current source and enable Photos. Lightroom Classic editing is still awaiting live platform certification.</p><a class="button button-wine" href="https://github.com/JeremySNR/Metachlorian/blob/main/docs/photos.md#start">Set up the source preview</a>''' if slug=='lightroom-classic-ai-photo-editing' else '''<h2>Find the shot in your footage.</h2><p>Download the free desktop app, or explore the illustrative sample before installing.</p><a class="button button-wine" href="/#get-started">Download free</a> <a class="text-link" href="/#demo">Explore the sample demo</a>'''
 toc=''.join(f'<a href="#{id}">{heading}</a>' for id,heading,_ in sections)
 document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(seo_title)} | Metachlorian</title><meta name="description" content="{html.escape(description)}"><meta name="theme-color" content="#efedf7"><link rel="canonical" href="{url}"><meta property="og:type" content="article"><meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(description)}"><meta property="og:url" content="{url}"><meta property="og:site_name" content="Metachlorian"><meta property="og:image" content="{origin}/assets/{image}"><meta property="og:image:alt" content="{image_alt}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{html.escape(title)}"><meta name="twitter:description" content="{html.escape(description)}"><meta name="twitter:image:alt" content="{image_alt}"><meta name="twitter:image" content="{origin}/assets/{image}">{favicon}<link rel="stylesheet" href="/foundations.css"><link rel="stylesheet" href="/tokens.css"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/family.css"><script defer src="/app.js"></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body class="guide-page"><a class="skip-link" href="#main">Skip to content</a>{header}<main id="main"><div class="guide-hero"><a class="guide-back" href="/">Metachlorian / Guides</a><h1>{title}</h1><p>{deck}</p></div><div class="guide-layout"><aside class="guide-toc"><span>In this guide</span>{toc}</aside><article class="guide-article">{contents}<div class="guide-cta">{cta}</div></article></div></main>{footer}</body></html>'''
 dest=root/'guides'/slug;dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(document, encoding='utf-8')
urls=[origin+'/']+[f'{origin}/guides/{p[0]}/' for p in pages]
(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{url}</loc></url>\n' for url in urls)+'</urlset>\n')
(root/'robots.txt').write_text(f'User-agent: *\nAllow: /\n\nSitemap: {origin}/sitemap.xml\n')
print(f'Generated {len(pages)} linked guides and crawl files.')
